    6→const execAsync = promisify(exec);
    7→
    8→export type HookEvent = "PreToolUse" | "PostToolUse" | "SessionStart" | "SessionEnd" | "AgentTurn";
    9→
   10→export interface HookDefinition {
   11→  event: HookEvent;
   12→  toolPattern?: string;  // regex pattern for tool name (e.g. "run_command|bash")
   13→  command: string;       // shell command to run
   14→  description?: string;
   15→}
   16→
   17→export interface HookResult {
   18→  blocked: boolean;
   19→  output: string;
   20→}
   21→
   22→export class HookEngine {
   23→  private hooks: HookDefinition[] = [];
   24→
   25→  add(hook: HookDefinition): void {
   26→    this.hooks.push(hook);
   27→  }
   28→
   29→  async loadFromFile(configPath: string = ".hooks.json"): Promise<void> {
   30→    try {
   31→      const content = await readFile(resolve(configPath), "utf-8");
   32→      const defs = JSON.parse(content) as HookDefinition[];
   33→      for (const h of defs) {
   34→        this.add(h);
   35→      }
   36→    } catch {
   37→      // No hooks file — that's fine
   38→    }
   39→  }
   40→
   41→  async fire(event: HookEvent, context: Record<string, string> = {}): Promise<HookResult> {
   42→    const relevant = this.hooks.filter((h) => h.event === event);
   43→
   44→    for (const hook of relevant) {
   45→      try {
   46→        const env = { ...process.env, ...context };
   47→        const { stdout, stderr } = await execAsync(hook.command, {
   48→          timeout: 10000,
   49→          env,
   50→        });
   51→        const output = [stdout, stderr].filter(Boolean).join("\n").trim();
   52→
   53→        // Exit code 2 = block the operation
   54→        if (output.includes("__BLOCK__")) {
   55→          return { blocked: true, output: output.replace("__BLOCK__", "").trim() };
   56→        }
   57→      } catch (err: unknown) {
   58→        const execErr = err as { code?: number; message?: string };
   59→        if (execErr.code === 2) {
   60→          return { blocked: true, output: execErr.message ?? "Hook blocked operation" };
   61→        }
   62→        // Other errors are non-fatal
   63→      }
   64→    }
   65→
   66→    return { blocked: false, output: "" };
   67→  }
   68→
   69→  async fireForTool(toolName: string, context: Record<string, string> = {}): Promise<HookResult> {
   70→    const relevant = this.hooks.filter((h) => {
   71→      if (h.event !== "PreToolUse" && h.event !== "PostToolUse") return false;
   72→      if (!h.toolPattern) return true; // No pattern = match all
   73→      return new RegExp(h.toolPattern).test(toolName);
   74→    });
   75→
   76→    for (const hook of relevant) {
   77→      try {
   78→        const env = { ...process.env, ...context, TOOL_NAME: toolName };
   79→        const { stdout } = await execAsync(hook.command, {
   80→          timeout: 10000,
   81→          env,
   82→        });
   83→        const output = stdout.trim();
   84→        if (output.includes("__BLOCK__")) {
   85→          return { blocked: true, output: output.replace("__BLOCK__", "").trim() };
   86→        }
   87→      } catch (err: unknown) {
   88→        const execErr = err as { code?: number; message?: string };
   89→        if (execErr.code === 2) {
   90→          return { blocked: true, output: execErr.message ?? "Hook blocked" };
   91→        }
   92→      }
   93→    }
   94→
   95→    return { blocked: false, output: "" };
   96→  }
   97→
   98→  list(): HookDefinition[] {
   99→    return [...this.hooks];
  100→  }
  101→}
