    3→export const todo_write_definition: ToolDefinition = {
    4→  type: "function",
    5→  function: {
    6→    name: "todo_write",
    7→    description:
    8→      "Track your task progress with a structured to-do list. " +
    9→      "Use to break down complex tasks and show progress to the user. " +
   10→      "Status: pending, in_progress, completed, cancelled.",
   11→    parameters: {
   12→      type: "object",
   13→      properties: {
   14→        action: {
   15→          type: "string",
   16→          enum: ["create", "update", "list", "clear"],
   17→          description: "Action: create new list, update status, list current, or clear all",
   18→        },
   19→        items: {
   20→          type: "string",
   21→          description: "JSON array of todo items for 'create': [{content, status, priority}]. " +
   22→            "Each item: {content: string, status: 'pending'|'in_progress'|'completed'|'cancelled', priority: 'high'|'medium'|'low'}",
   23→        },
   24→        index: {
   25→          type: "number",
   26→          description: "Item index (0-based) for 'update' action",
   27→        },
   28→        status: {
   29→          type: "string",
   30→          enum: ["pending", "in_progress", "completed", "cancelled"],
   31→          description: "New status for 'update' action",
   32→        },
   33→        content: {
   34→          type: "string",
   35→          description: "New content for 'update' action (optional)",
   36→        },
   37→      },
   38→      required: ["action"],
   39→    },
   40→  },
   41→};
   42→
   43→interface TodoItem {
   44→  content: string;
   45→  status: "pending" | "in_progress" | "completed" | "cancelled";
   46→  priority: "high" | "medium" | "low";
   47→}
   48→
   49→let currentTodos: TodoItem[] = [];
   50→
   51→export const todo_write_handler: ToolHandler = async (args) => {
   52→  const action = args.action as string;
   53→
   54→  switch (action) {
   55→    case "create": {
   56→      if (!args.items) return { content: "Error: 'items' required for create", isError: true };
   57→      try {
   58→        const items = JSON.parse(args.items as string) as TodoItem[];
   59→        currentTodos = items.map((i) => ({
   60→          content: i.content ?? "",
   61→          status: i.status ?? "pending",
   62→          priority: i.priority ?? "medium",
   63→        }));
   64→        return { content: formatTodos(currentTodos, "Created task list") };
   65→      } catch {
   66→        return { content: "Error: Invalid JSON in 'items'", isError: true };
   67→      }
   68→    }
   69→
   70→    case "update": {
   71→      const index = args.index as number;
   72→      if (index === undefined || index < 0 || index >= currentTodos.length) {
   73→        return { content: `Error: Invalid index ${index}. List has ${currentTodos.length} items.`, isError: true };
   74→      }
   75→      if (args.status) currentTodos[index].status = args.status as TodoItem["status"];
   76→      if (args.content) currentTodos[index].content = args.content as string;
   77→      return { content: formatTodos(currentTodos, `Updated item ${index}`) };
   78→    }
   79→
   80→    case "list":
   81→      if (currentTodos.length === 0) return { content: "No tasks tracked." };
   82→      return { content: formatTodos(currentTodos, "Current tasks") };
   83→
   84→    case "clear":
   85→      currentTodos = [];
   86→      return { content: "Task list cleared." };
   87→
   88→    default:
   89→      return { content: `Unknown action: ${action}`, isError: true };
   90→  }
   91→};
   92→
   93→function formatTodos(todos: TodoItem[], title: string): string {
   94→  const statusIcon: Record<string, string> = {
   95→    pending: "○",
   96→    in_progress: "●",
   97→    completed: "✓",
   98→    cancelled: "✗",
   99→  };
  100→
  101→  const lines = [`${title}:\n`];
  102→  for (let i = 0; i < todos.length; i++) {
  103→    const t = todos[i];
  104→    const icon = statusIcon[t.status] ?? "?";
  105→    const prio = t.priority === "high" ? "[!]" : t.priority === "low" ? "[_]" : "   ";
  106→    lines.push(`  ${i}. ${icon} ${prio} ${t.content} [${t.status}]`);
  107→  }
  108→
  109→  const stats = {
  110→    completed: todos.filter((t) => t.status === "completed").length,
  111→    in_progress: todos.filter((t) => t.status === "in_progress").length,
  112→    pending: todos.filter((t) => t.status === "pending").length,
  113→    total: todos.length,
  114→  };
  115→  lines.push(`\nProgress: ${stats.completed}/${stats.total} done, ${stats.in_progress} in progress`);
  116→
  117→  return lines.join("\n");
  118→}
