    3→/**
    4→ * Real token counter using tiktoken.
    5→ * Supports OpenAI models (GPT-4, GPT-3.5) and approximate for other models.
    6→ */
    7→export class TokenCounter {
    8→  private encoder: Tiktoken | null = null;
    9→  private fallbackRatio = 4; // ~4 chars per token fallback
   10→
   11→  constructor() {
   12→    try {
   13→      // Use cl100k_base encoding (GPT-4/GPT-3.5-turbo)
   14→      this.encoder = encoding_for_model("gpt-4");
   15→    } catch {
   16→      this.encoder = null;
   17→    }
   18→  }
   19→
   20→  /**
   21→   * Count tokens in a string.
   22→   */
   23→  count(text: string): number {
   24→    if (this.encoder) {
   25→      try {
   26→        return this.encoder.encode(text).length;
   27→      } catch {
   28→        return Math.ceil(text.length / this.fallbackRatio);
   29→      }
   30→    }
   31→    return Math.ceil(text.length / this.fallbackRatio);
   32→  }
   33→
   34→  /**
   35→   * Count tokens in a message array.
   36→   */
   37→  countMessages(messages: Array<{ role: string; content: string | null | Array<{ type: string; text?: string }> }>): number {
   38→    let total = 0;
   39→
   40→    for (const msg of messages) {
   41→      // Each message has ~4 overhead tokens (role, separators)
   42→      total += 4;
   43→
   44→      if (typeof msg.content === "string") {
   45→        total += this.count(msg.content);
   46→      } else if (Array.isArray(msg.content)) {
   47→        for (const part of msg.content) {
   48→          if ("text" in part && part.text) {
   49→            total += this.count(part.text);
   50→          }
   51→        }
   52→      }
   53→    }
   54→
   55→    total += 2; // reply priming
   56→    return total;
   57→  }
   58→
   59→  /**
   60→   * Estimate how many tokens to keep for response.
   61→   */
   62→  remainingTokens(used: number, maxContext: number = 200_000, maxOutput: number = 4096): number {
   63→    return Math.max(0, maxContext - used - maxOutput);
   64→  }
   65→
   66→  /**
   67→   * Check if context is approaching limit.
   68→   */
   69→  shouldCompact(used: number, maxContext: number = 200_000): boolean {
   70→    return used > maxContext * 0.85;
   71→  }
   72→
   73→  /**
   74→   * Truncate text to fit within token limit.
   75→   */
   76→  truncate(text: string, maxTokens: number): string {
   77→    const tokenCount = this.count(text);
   78→    if (tokenCount <= maxTokens) return text;
   79→
   80→    const ratio = maxTokens / tokenCount;
   81→    const charLimit = Math.floor(text.length * ratio * 0.9); // 90% safety margin
   82→    return text.slice(0, charLimit) + "\n... (truncated)";
   83→  }
   84→
   85→  /**
   86→   * Estimate cost for a model.
   87→   */
   88→  estimateCost(inputTokens: number, outputTokens: number, model: string): number {
   89→    const rates: Record<string, { input: number; output: number }> = {
   90→      "gpt-4o": { input: 2.50 / 1_000_000, output: 10 / 1_000_000 },
   91→      "gpt-4o-mini": { input: 0.15 / 1_000_000, output: 0.60 / 1_000_000 },
   92→      "gpt-5.2": { input: 5 / 1_000_000, output: 15 / 1_000_000 },
   93→      "claude-sonnet-4.6": { input: 3 / 1_000_000, output: 15 / 1_000_000 },
   94→      "claude-opus-4": { input: 15 / 1_000_000, output: 75 / 1_000_000 },
   95→    };
   96→
   97→    const rate = rates[model] ?? { input: 2 / 1_000_000, output: 8 / 1_000_000 };
   98→    return inputTokens * rate.input + outputTokens * rate.output;
   99→  }
  100→
  101→  /**
  102→   * Free the encoder when done.
  103→   */
  104→  free(): void {
  105→    if (this.encoder) {
  106→      try { this.encoder.free(); } catch { /* already freed */ }
  107→      this.encoder = null;
  108→    }
  109→  }
  110→}
  111→
  112→// Singleton instance
  113→let counter: TokenCounter | null = null;
  114→
  115→export function getTokenCounter(): TokenCounter {
  116→  if (!counter) counter = new TokenCounter();
  117→  return counter;
  118→}
